export const weapons={M4A1:{damage:26,rate:100,mag:30,reload:1800,range:100},AK74:{damage:32,rate:140,mag:30,reload:2200,range:100},MP5:{damage:21,rate:80,mag:30,reload:1500,range:60},M24:{damage:85,rate:1100,mag:5,reload:2600,range:160},M9:{damage:30,rate:250,mag:15,reload:1200,range:50}};
export const boxes=[[-15,3,0,8,6,20],[15,3,-5,8,6,20],[0,2,-17,14,4,7],[-5,1,4,4,2,3],[7,1,10,5,2,3],[-22,1,18,5,2,4],[23,1,-20,5,2,4],[0,1,-3,3,2,3],[-27,3,-8,5,6,12],[27,3,10,5,6,12]];
export function blocked(x,z){return Math.abs(x)>31||Math.abs(z)>31||boxes.some(b=>Math.abs(x-b[0])<b[3]/2+.45&&Math.abs(z-b[2])<b[5]/2+.45)}
export function move(p,i,dt){let x=Number(i.x)||0,z=Number(i.z)||0;const n=Math.max(1,Math.hypot(x,z));const speed=i.crouch?2.4:i.sprint?7:4.5; x=x/n*speed*dt;z=z/n*speed*dt;if(!blocked(p.x+x,p.z))p.x+=x;if(!blocked(p.x,p.z+z))p.z+=z;}
export function rayBox(o,d,b){let lo=0,hi=1e6;for(let k=0;k<3;k++){const min=b[k]-b[k+3]/2,max=b[k]+b[k+3]/2;if(Math.abs(d[k])<1e-7){if(o[k]<min||o[k]>max)return Infinity;continue}let a=(min-o[k])/d[k],c=(max-o[k])/d[k];if(a>c)[a,c]=[c,a];lo=Math.max(lo,a);hi=Math.min(hi,c);if(hi<lo)return Infinity}return lo}
export function createPlayer(id,name,team,weapon='M4A1'){if(!Object.hasOwn(weapons,weapon))weapon='M4A1';return {id,name:name.slice(0,20),team,x:team===0?-24:24,z:team===0?-26:26,y:0,vy:0,yaw:0,pitch:0,hp:100,ammo:weapons[weapon]?.mag||30,reserve:120,weapon:weapons[weapon]?weapon:'M4A1',kills:0,deaths:0,assists:0,grenades:2,primary:weapon,slots:{},seq:0,lastShot:0,reloadAt:0,respawnAt:0}}
export function spawn(p){p.x=p.team===0?-24:24;p.z=p.team===0?-26:26;p.hp=100;p.y=0;p.vy=0;p.ammo=weapons[p.weapon].mag;p.reserve=120;p.grenades=2;p.slots={};p.respawnAt=0}

export function explosionDamage(distance){return distance>=8?0:Math.round(120*(1-distance/8))}
